/*
 Problem: 4006. Count Valid Prefixes
 Language: cpp
 Runtime: 0 ms (100.00%)
 Memory: 9.5 MB (56.51%)
 Tags: String, Counting
*/
class Solution {
public:
    int countValidPrefixes(string s) {
        vector<int> cnt(2, 0);
        int ans = 0;

        for (const auto& c : s) {
            ++cnt[c - '0'];

            if (abs(cnt[0] - cnt[1]) <= 1) ++ans;
        }

        return ans;
    }
};
